insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('706b6620-fdaf-5751-a61a-cda8be10dc47', 'ed876f60-9f86-5aa2-a19b-b7e4b20d1204', '34e3ae53-12ea-5373-ad53-b8d55ce6dfe1', '4ff4d7e7-e2a4-5d7d-aff1-ccd83641ef92', 'Which is a supply-side policy?', '["Increasing spending on education and training","Cutting exports","Raising interest rates","Increasing unemployment benefits"]'::jsonb, 'Training raises labour productivity and shifts LRAS right.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
