insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('edd80e04-2e5f-5ca6-ad94-4c0e6eb76104', 'ed876f60-9f86-5aa2-a19b-b7e4b20d1204', '34e3ae53-12ea-5373-ad53-b8d55ce6dfe1', '4ff4d7e7-e2a4-5d7d-aff1-ccd83641ef92', 'A limitation of supply-side policies is that they…', '["Reduce productive capacity","Take a long time to have an effect","Always cause inflation","Cannot be used by governments"]'::jsonb, 'Education and infrastructure take years to raise capacity.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
